/* ============ VIEW: REPORTS ============ */
/* portfolio management metrics — aggregate KPI health across all evaluated innovators */
function portfolioBlock(apps) {
  const evald = apps.filter(a => (a.kpiSheets || []).length);
  if (!evald.length) return `
    <div class="ams-card"><h3>Portfolio Health (KPI)</h3>
      <div class="empty-state">No KPI evaluation sheets completed yet — portfolio metrics appear here once innovators are scored.</div></div>`;
  const lat = (a) => a.kpiSheets[0];
  const n = evald.length;
  const avg = Math.round(evald.reduce((s, a) => s + lat(a).pct, 0) / n);
  const goodN = evald.filter(a => lat(a).pct >= 60).length;
  const riskN = evald.filter(a => lat(a).pct < 40).length;
  const goodPct = Math.round(goodN / n * 100), riskPct = Math.round(riskN / n * 100);
  const dist = {};
  const stageDist = {};
  evald.forEach(a => {
    const r = (lat(a).rating || "?").split(" — ")[0];
    dist[r] = (dist[r] || 0) + 1;
    const st = lat(a).values?.v_a1_stage || "Not scored";
    stageDist[st] = (stageDist[st] || 0) + 1;
  });
  const sum = (k) => evald.reduce((s, a) => s + (+lat(a).values?.["v_" + k] || 0), 0);
  const scaled = evald.filter(a => lat(a).values?.v_a1_stage === "Scaling").length;
  const investReady = evald.filter(a => lat(a).pct >= 80).length;
  const tgt = (ok, text) => `<td class="text-right ${ok ? "kpi-ok" : "kpi-bad"}">${ok ? "✓" : "✗"} ${text}</td>`;
  return `
    <div class="grid-2col">
      <div class="ams-card"><h3>Portfolio Health (KPI Framework)</h3>
        <table class="tbl"><tbody>
          <tr><td>Innovators evaluated</td><td class="text-right"><b>${n}</b></td><td></td></tr>
          <tr><td>Average score</td><td class="text-right"><b>${avg}%</b></td>${tgt(avg > 60, "target &gt;60")}</tr>
          <tr><td>% Excellent / Good</td><td class="text-right"><b>${goodPct}%</b></td>${tgt(goodPct > 70, "target &gt;70%")}</tr>
          <tr><td>% At Risk / Critical</td><td class="text-right"><b>${riskPct}%</b></td>${tgt(riskPct < 15, "target &lt;15%")}</tr>
          <tr><td>Rating distribution</td><td colspan="2" class="text-right sub2">
            ${["Excellent", "Good", "Developing", "At Risk", "Critical"].map(r => `${r}: ${dist[r] || 0}`).join(" · ")}</td></tr>
          <tr><td>Development stage distribution</td><td colspan="2" class="text-right sub2">
            ${Object.entries(stageDist).map(([k, v]) => `${escA(k)}: ${v}`).join(" · ")}</td></tr>
        </tbody></table>
      </div>
      <div class="ams-card"><h3>Portfolio Impact <span class="sub2">(from latest KPI sheets)</span></h3>
        <table class="tbl"><tbody>
          <tr><td>Total innovators supported</td><td class="text-right"><b>${apps.length}</b></td></tr>
          <tr><td>Total beneficiaries reached</td><td class="text-right"><b>${sum("c1_direct").toLocaleString()}</b></td></tr>
          <tr><td>Total revenue generated</td><td class="text-right"><b>${amsMoney(sum("b2_revenue"))}</b></td></tr>
          <tr><td>Total jobs created</td><td class="text-right"><b>${sum("c3_jobs")}</b></td></tr>
          <tr><td>Innovations scaled (multi-site)</td><td class="text-right"><b>${scaled}</b></td></tr>
          <tr><td>Investment-ready innovations</td><td class="text-right"><b>${investReady}</b></td></tr>
        </tbody></table>
      </div>
    </div>`;
}

function viewReports(el) {
  const fFrom = P.get("from") || "", fTo = P.get("to") || "";
  const fSector = P.get("sector") || "", fStage = P.get("stage") || "";
  const fStatus = P.get("status") || "", fAssigned = P.get("assigned") || "";
  const fScope = P.get("scope") || "";
  const rType = P.get("r") || "all", rId = P.get("id") || "";
  const allApps = amsGetApplicants();
  const staffList = amsGetStaff();
  const roles = amsGetRoles();
  const sectors = [...new Set(allApps.map(a => a.sector).filter(Boolean))].sort();
  const assignees = [...new Set(allApps.map(a => a.assignedToName).filter(Boolean))].sort();

  let apps = allApps.filter(a =>
    (!fFrom || (a.appliedDate || "") >= fFrom) &&
    (!fTo || (a.appliedDate || "") <= fTo) &&
    (!fSector || a.sector === fSector) &&
    (!fStage || a.stage === fStage) &&
    (!fStatus || a.status === fStatus || a.outcome === fStatus) &&
    (!fAssigned || a.assignedToName === fAssigned) &&
    (!fScope || (fScope === "in" ? a.inScope : !a.inScope)));

  const rSel = { all: "Everything", applicant: "One applicant", staff: "One staff member", sector: "One sector",
    tasks: "Tasks only", meetings: "Meetings only", procurement: "Procurement only", evaluations: "Evaluations only" };
  let reportLabel = rSel[rType] || "Everything";
  let staffFocus = null;
  if (rType === "applicant" && rId) {
    apps = apps.filter(a => a.id === rId);
    reportLabel += " — " + (apps[0] ? (apps[0].name + " (" + (apps[0].applicantName || "") + ")") : rId);
  } else if (rType === "staff" && rId) {
    staffFocus = staffList.find(s => s.id === rId);
    if (staffFocus) { apps = apps.filter(a => a.assignedToName === staffFocus.name); reportLabel += " — " + staffFocus.name; }
  } else if (rType === "sector" && rId) {
    apps = apps.filter(a => a.sector === rId); reportLabel += " — " + rId;
  }

  let tasks = allTasks().filter(t => !t.appId || apps.some(a => a.id === t.appId) || t.internal);
  if (staffFocus) tasks = tasks.filter(t => t.assignedTo === staffFocus.name || t.by === staffFocus.name || t.byId === staffFocus.id);
  if (rType === "tasks" && rId) tasks = tasks.filter(t => t.assignedTo === rId || t.byId === rId);

  const only = { tasks: ["summary", "tasks"], meetings: ["summary", "meetings"],
    procurement: ["summary", "procurement"], evaluations: ["summary", "evaluations"] }[rType] || null;
  const sec = n => !only || only.includes(n);

  const support = apps.reduce((s, a) => s + (a.supportApproved || 0), 0);
  const spent = apps.reduce((s, a) => s + (a.spent || 0), 0);
  const byStage = STAGES.map(s => ({ label: s, value: apps.filter(a => a.stage === s).length, color: STAGE_COLORS[s] }));
  const sectorMap = {};
  apps.forEach(a => sectorMap[a.sector || "Other"] = (sectorMap[a.sector || "Other"] || 0) + 1);
  const secColors = ["#22c55e", "#3b82f6", "#8b5cf6", "#f59e0b", "#ec4899", "#64748b"];
  const sectorSegs = Object.entries(sectorMap).map(([k, v], i) => ({ label: k, value: v, color: secColors[i % secColors.length] }));

  const decisions = apps.reduce((s, a) => s + (a.decisions || []).length, 0);
  let meetings = apps.flatMap(a => (a.meetings || []).map(m => ({ ...m, appName: a.name })));
  let prs = apps.flatMap(a => (a.procurement || []).map(p => ({ ...p, appName: a.name })));
  let evals = apps.flatMap(a => (a.evaluations || []).map(e => ({ ...e, appName: a.name })));
  if (staffFocus) {
    evals = evals.filter(e => e.expert === staffFocus.name || e.by === staffFocus.name);
    meetings = meetings.filter(m => m.by === staffFocus.name || m.owner === staffFocus.name);
  }
  const prsPending = prs.filter(p => p.status === "Pending");
  const prsApproved = prs.filter(p => p.status === "Approved");
  const pendingVal = prsPending.reduce((s, p) => s + (p.amount || 0), 0);
  const apprVal = prsApproved.reduce((s, p) => s + (p.amount || 0), 0);
  const supportReq = {};
  apps.forEach(a => (a.supportRequested || []).forEach(s => supportReq[s] = (supportReq[s] || 0) + 1));
  const byAssignee = {};
  tasks.forEach(t => {
    byAssignee[t.assignedTo] = byAssignee[t.assignedTo] || { open: 0, overdue: 0, done: 0 };
    if (t.status === "Completed") byAssignee[t.assignedTo].done++;
    else { byAssignee[t.assignedTo].open++; if (daysUntil(t.due) < 0) byAssignee[t.assignedTo].overdue++; }
  });
  const staffPerf = staffFocus ? {
    tasksDone: tasks.filter(t => t.status === "Completed" && (t.assignedTo === staffFocus.name || t.byId === staffFocus.id)).length,
    tasksOpen: tasks.filter(t => t.status !== "Completed" && (t.assignedTo === staffFocus.name || t.byId === staffFocus.id)).length,
    evalsDone: evals.length,
    meetingsHeld: meetings.length,
    appsHandled: apps.length,
  } : null;

  /* ---- narrative data for the professional summary ---- */
  const underEvalN = apps.filter(a => a.stage === "Under Evaluation" || a.stage === "Pitch Deck").length;
  const activeN = apps.filter(a => a.status === "Active").length;
  const staleN = apps.filter(a => a.status === "Active" && amsDaysSince(a.lastActivity) > amsGetSettings().inactiveDays).length;
  const overdueT = tasks.filter(t => t.status !== "Completed" && daysUntil(t.due) < 0).length;
  const openT = tasks.filter(t => t.status !== "Completed").length;
  const doneT = tasks.filter(t => t.status === "Completed").length;
  const utilization = support ? Math.round(spent / support * 100) : 0;
  const today = new Date().toISOString().slice(0, 10);
  const periodText = fFrom || fTo ? `from ${fFrom ? amsFmtDate(fFrom) : "the beginning"} to ${fTo ? amsFmtDate(fTo) : "the present"}` : "the full reporting period";
  const topSector = Object.entries(sectorMap).sort((a, b) => b[1] - a[1])[0];

  const execParas = [
    `During ${periodText}, the Kurdistan Innovation Institute recorded <b>${apps.length}</b> application(s) in scope of this report, of which <b>${activeN}</b> are active projects and <b>${underEvalN}</b> are currently under evaluation or awaiting pitch review. ${topSector ? `The largest sector represented is <b>${escA(topSector[0])}</b> with ${topSector[1]} application(s).` : ""}`,
    `Financially, approved support commitments total <b>${amsMoney(support)}</b>, of which <b>${amsMoney(spent)}</b> has been spent (${utilization}% utilization), leaving <b>${amsMoney(support - spent)}</b> available. Procurement activity comprises <b>${prs.length}</b> purchase request(s): ${prsPending.length} pending (${amsMoney(pendingVal)}) and ${prsApproved.length} approved (${amsMoney(apprVal)}).`,
    `Operationally, the team logged <b>${tasks.length}</b> task(s) — ${openT} open and ${doneT} completed, with <b>${overdueT}</b> overdue — and conducted <b>${meetings.length}</b> meeting(s). <b>${decisions}</b> formal decision(s) were recorded. ${staleN ? `<b>${staleN}</b> active applicant(s) have shown no activity beyond the inactivity threshold and require follow-up.` : "No applicants currently exceed the inactivity threshold."}`,
  ];

  const findings = [
    apps.length ? `${apps.length} application(s) analysed across ${Object.keys(sectorMap).length || 0} sector(s); ${byStage.reduce((s, x) => s + x.value, 0)} reach the stage distribution shown in Section 3.` : "No applications match the selected filters.",
    underEvalN ? `${underEvalN} case(s) are in the evaluation pipeline — ensure expert reviewers are assigned to avoid delays.` : "No cases are currently awaiting evaluation.",
    overdueT ? `${overdueT} task(s) are overdue and should be re-prioritised or their deadlines renegotiated.` : "No tasks are currently overdue.",
    prsPending.length ? `${prsPending.length} purchase request(s) worth ${amsMoney(pendingVal)} await approval.` : "No purchase requests are pending approval.",
    utilization >= 80 ? `Support utilisation is high (${utilization}%) — plan additional funding requests for active projects.` : utilization > 0 ? `Support utilisation stands at ${utilization}%; remaining balance is ${amsMoney(support - spent)}.` : "No support has been committed yet.",
    staleN ? `${staleN} applicant(s) are inactive beyond the threshold — consider outreach or closure.` : "Applicant activity levels are healthy.",
  ];

  const recommendations = [
    overdueT ? `Clear or reschedule the ${overdueT} overdue task(s) within the next week.` : null,
    prsPending.length ? `Review and decide the ${prsPending.length} pending purchase request(s) totalling ${amsMoney(pendingVal)}.` : null,
    staleN ? `Contact the ${staleN} inactive applicant(s) or move them toward closure.` : null,
    underEvalN ? `Assign evaluators to the ${underEvalN} case(s) awaiting evaluation to keep the pipeline moving.` : null,
    !overdueT && !prsPending.length && !staleN && !underEvalN ? "No urgent actions identified — maintain current cadence of reviews and reporting." : null,
  ].filter(Boolean);

  const filterDesc = [fFrom && `from ${amsFmtDate(fFrom)}`, fTo && `to ${amsFmtDate(fTo)}`,
    fSector, fStage, fStatus, fAssigned && `assigned ${fAssigned}`, fScope].filter(Boolean).join(" · ") || "All records";
  const th = `<th style="text-align:left">Applicant</th><th style="text-align:left">Project</th><th>Sector</th><th>Stage</th><th>Status / Outcome</th><th>Assigned</th><th>Applied</th><th>Progress</th><th>Support Approved</th>`;

  el.innerHTML = `
    <div class="page-head-row no-print">
      <div><div class="page-title">Reports</div>
      <div class="page-sub">Program report — generated ${amsFmtDate(new Date().toISOString())}</div></div>
      <div class="qa-row">
        <button class="abtn ghost sm" id="csvApps">${IC.doc} Applicants CSV</button>
        <button class="abtn ghost sm" id="csvTasks">${IC.doc} Tasks CSV</button>
        <button class="abtn ghost sm" id="csvEvals">${IC.doc} Evaluations CSV</button>
        <button class="abtn ghost sm" id="csvMeet">${IC.doc} Meetings CSV</button>
        <button class="abtn ghost sm" id="csvPR">${IC.doc} Procurement CSV</button>
        <button class="abtn sm" onclick="window.print()">${IC.report} Print Report</button>
      </div>
    </div>

    <form id="reportFilters" class="filter-bar no-print" style="flex-wrap:wrap">
      <label>Report on <select name="r" id="rType">
        ${Object.entries(rSel).map(([k, v]) => `<option value="${k}" ${k === rType ? "selected" : ""}>${v}</option>`).join("")}
      </select></label>
      <label>Entity <select name="id" id="rEntity">
        <option value="">—</option>
        ${rType === "staff" ? staffList.map(s => `<option value="${escA(s.id)}" ${s.id === rId ? "selected" : ""}>${escA(s.name)}</option>`).join("")
          : rType === "sector" ? sectors.map(s => `<option value="${escA(s)}" ${s === rId ? "selected" : ""}>${escA(s)}</option>`).join("")
          : rType === "tasks" ? staffList.map(s => `<option value="${escA(s.name)}" ${s.name === rId ? "selected" : ""}>${escA(s.name)}</option>`).join("")
          : apps.length ? apps.map(a => `<option value="${escA(a.id)}" ${a.id === rId ? "selected" : ""}>${escA(a.name)}</option>`).join("") : ""}
      </select></label>
      <label>From <input type="date" name="from" value="${escA(fFrom)}"></label>
      <label>To <input type="date" name="to" value="${escA(fTo)}"></label>
      <label>Sector <select name="sector"><option value="">All</option>
        ${sectors.map(s => `<option ${s === fSector ? "selected" : ""}>${escA(s)}</option>`).join("")}</select></label>
      <label>Stage <select name="stage"><option value="">All</option>
        ${STAGES.map(s => `<option ${s === fStage ? "selected" : ""}>${escA(s)}</option>`).join("")}</select></label>
      <label>Status <select name="status"><option value="">All</option>
        ${["Active", "Inactive", "Under Evaluation", "Pitch Deck", "Rejected", "Withdrawn", "Approved", "Submitted Form"].map(s => `<option ${s === fStatus ? "selected" : ""}>${escA(s)}</option>`).join("")}</select></label>
      <label>Assigned <select name="assigned"><option value="">All</option>
        ${assignees.map(s => `<option ${s === fAssigned ? "selected" : ""}>${escA(s)}</option>`).join("")}</select></label>
      <label>Scope <select name="scope"><option value="">All</option>
        <option value="in" ${fScope === "in" ? "selected" : ""}>In scope</option>
        <option value="out" ${fScope === "out" ? "selected" : ""}>Out of scope</option></select></label>
      <button class="abtn sm" type="submit">Apply</button>
      <a class="abtn ghost sm" href="?v=reports">Reset</a>
    </form>

    <div class="report-sheet">
      <!-- letterhead -->
      <div class="letterhead">
        <img src="asset/kii_logocl.png" alt="KII" class="report-logo">
        <div class="letterhead-mid">
          <div class="lh-name">Kurdistan Innovation Institute</div>
          <div class="lh-line">Application Management System · Program Monitoring Report</div>
          <div class="lh-line2">${escA(amsGetSettings().callName)} · ${escA(reportLabel)}</div>
        </div>
        <table class="lh-meta"><tbody>
          <tr><td>Report No.</td><td>KII-RPT-${today.replace(/-/g, "")}-${amsUid("n").slice(-4).toUpperCase()}</td></tr>
          <tr><td>Date</td><td>${amsFmtDate(today)}</td></tr>
          <tr><td>Period</td><td>${escA(periodText)}</td></tr>
          <tr><td>Prepared by</td><td>${escA(staff.name)}</td></tr>
          <tr><td>Classification</td><td><b>Confidential — Internal</b></td></tr>
        </tbody></table>
      </div>
      <div class="filter-note">Scope of data: ${escA(filterDesc)}</div>

      <!-- 1. executive summary -->
      <h2 class="report-sec"><span class="sec-no">1</span> Executive Summary</h2>
      <div class="exec-body">
        ${execParas.map(p => `<p>${p}</p>`).join("")}
        <div class="kpi-strip">
          <div class="kpi"><b>${apps.length}</b><span>Applicants</span></div>
          <div class="kpi"><b>${underEvalN}</b><span>Under evaluation</span></div>
          <div class="kpi"><b>${amsMoney(support)}</b><span>Support committed</span></div>
          <div class="kpi"><b>${utilization}%</b><span>Utilized</span></div>
          <div class="kpi"><b>${overdueT}</b><span>Overdue tasks</span></div>
        </div>
      </div>

      <!-- 2. findings -->
      ${sec("summary") || sec("stage") || sec("financial") || sec("register") || sec("procurement") || sec("meetings") || sec("tasks") || sec("evaluations") || sec("portfolio") || sec("staff") ? `<h2 class="report-sec"><span class="sec-no">2</span> Key Findings</h2>
      <ul class="findings">${findings.map(f => `<li>${f}</li>`).join("")}</ul>` : ""}

      <!-- 3. recommendations -->
      <h2 class="report-sec"><span class="sec-no">3</span> Recommendations</h2>
      <ol class="recs">${recommendations.map(r => `<li>${r}</li>`).join("")}</ol>

      <!-- detail sections -->
      ${staffFocus ? `<h2 class="report-sec"><span class="sec-no">4</span> Staff Performance — ${escA(staffFocus.name)}</h2>
      <table class="tbl report-tbl"><tbody>
        <tr><td>Role / Title</td><td class="text-right"><b>${escA(roles[staffFocus.role]?.label || staffFocus.role)} · ${escA(staffFocus.title || "")}</b></td>
        <td>Status</td><td class="text-right"><b>${staffFocus.active ? "Active" : "Restricted"}</b></td>
        <td>Email</td><td class="text-right"><b>${escA(staffFocus.email)}</b></td></tr>
        <tr><td>Tasks completed</td><td class="text-right"><b>${staffPerf.tasksDone}</b></td>
        <td>Open / in progress</td><td class="text-right"><b>${staffPerf.tasksOpen}</b></td>
        <td>Evaluations submitted</td><td class="text-right"><b>${staffPerf.evalsDone}</b></td></tr>
        <tr><td>Meetings</td><td class="text-right"><b>${staffPerf.meetingsHeld}</b></td>
        <td>Applicants handled</td><td class="text-right"><b>${staffPerf.appsHandled}</b></td>
        <td></td><td></td></tr>
      </tbody></table>` : ""}

      ${sec("stage") ? `<h2 class="report-sec"><span class="sec-no">${staffFocus ? "5" : "4"}</span> Programme Data — Stage &amp; Sector Distribution</h2>
      <div class="grid-2col">
        <div class="ams-card"><h3>Applications by Stage</h3>${barChart(byStage)}</div>
        <div class="ams-card"><h3>Sector Distribution</h3>${donut(sectorSegs, apps.length, "Total")}</div>
      </div>` : ""}

      ${sec("financial") ? `<h2 class="report-sec"><span class="sec-no">${staffFocus ? "6" : "5"}</span> Financial Overview</h2>
      <table class="tbl report-tbl"><tbody>
        <tr><td>Total approved support</td><td class="text-right"><b>${amsMoney(support)}</b></td>
        <td>Total spent</td><td class="text-right"><b>${amsMoney(spent)}</b></td>
        <td>Remaining</td><td class="text-right"><b class="money-green">${amsMoney(support - spent)}</b></td>
        <td>Utilization</td><td class="text-right"><b>${utilization}%</b></td></tr>
      </tbody></table>
      <div class="sub2" style="margin-top:6px">Support requested: ${Object.entries(supportReq).map(([k, v]) => `${escA(k)} ×${v}`).join(" · ") || "—"}</div>` : ""}

      ${sec("register") ? `<h2 class="report-sec"><span class="sec-no">${staffFocus ? "7" : "6"}</span> Appendix A — Applicant Register (${apps.length})</h2>
      <table class="tbl report-tbl"><thead><tr>${th}</tr></thead><tbody>
        ${apps.map(a => `<tr>
          <td><b>${escA(a.applicantName || "—")}</b></td><td>${escA(a.name)}</td><td>${escA(a.sector || "—")}</td>
          <td>${escA(a.stage)}</td><td>${escA(a.status)}${a.outcome ? ` / ${escA(a.outcome)}` : ""}</td>
          <td>${escA(a.assignedToName || "—")}</td><td>${amsFmtDate(a.appliedDate)}</td><td>${a.progress ?? 0}%</td>
          <td>${a.supportApproved ? amsMoney(a.supportApproved) : "—"}</td></tr>`).join("")
          || '<tr><td colspan="9"><div class="empty-state">No applicants match the filters.</div></td></tr>'}
      </tbody></table>` : ""}

      ${sec("procurement") ? `<h2 class="report-sec"><span class="sec-no">${staffFocus ? "8" : "7"}</span> Appendix B — Procurement (${prs.length})</h2>
      <table class="tbl report-tbl"><tbody>
        <tr><td>Pending PRs</td><td class="text-right"><b>${prsPending.length}</b></td>
        <td>Pending value</td><td class="text-right"><b>${amsMoney(pendingVal)}</b></td>
        <td>Approved PRs</td><td class="text-right"><b>${prsApproved.length}</b></td>
        <td>Approved value</td><td class="text-right"><b>${amsMoney(apprVal)}</b></td></tr>
      </tbody></table>
      ${prs.length ? `<table class="tbl report-tbl" style="margin-top:10px"><thead><tr>
        <th>PR #</th><th style="text-align:left">Applicant / Project</th><th style="text-align:left">Title</th><th>Amount</th><th>Date</th><th>Status</th></tr></thead><tbody>
        ${prs.map(p => `<tr><td>${escA(p.number || p.id || "—")}</td><td>${escA(p.appName)}</td><td>${escA(p.title || p.desc || "—")}</td>
          <td>${p.amount ? amsMoney(p.amount) : "—"}</td><td>${amsFmtDate(p.date)}</td><td>${escA(p.status)}</td></tr>`).join("")}
      </tbody></table>` : '<div class="empty-state">No purchase requests.</div>'}` : ""}

      ${sec("meetings") ? `<h2 class="report-sec"><span class="sec-no">${staffFocus ? "9" : "8"}</span> Appendix C — Meetings (${meetings.length})</h2>
      <table class="tbl report-tbl"><thead><tr>
        <th style="text-align:left">Applicant / Project</th><th style="text-align:left">Meeting</th><th>Date</th><th>Time</th><th style="text-align:left">Location</th><th>Status</th></tr></thead><tbody>
        ${meetings.map(m => `<tr><td>${escA(m.appName)}</td><td>${escA(m.title)}</td><td>${amsFmtDate(m.date)}</td>
          <td>${escA(m.time || "—")}</td><td>${escA(m.location || "—")}</td><td>${escA(m.status)}</td></tr>`).join("")
          || '<tr><td colspan="6"><div class="empty-state">No meetings.</div></td></tr>'}
      </tbody></table>` : ""}

      ${sec("tasks") ? `<h2 class="report-sec"><span class="sec-no">${staffFocus ? "10" : "9"}</span> Appendix D — Tasks (${tasks.length})</h2>
      <table class="tbl report-tbl"><tbody>
        <tr><td>Open</td><td class="text-right"><b>${openT}</b></td>
        <td>Overdue</td><td class="text-right"><b>${overdueT}</b></td>
        <td>Completed</td><td class="text-right"><b>${doneT}</b></td></tr>
      </tbody></table>
      <table class="tbl report-tbl" style="margin-top:10px"><thead><tr>
        <th style="text-align:left">Task</th><th style="text-align:left">Description</th><th>Applicant</th><th>Assigned To</th><th>Due</th><th>Status</th><th>Priority</th></tr></thead><tbody>
        ${tasks.slice(0, 80).map(t => `<tr><td><b>${escA(t.task)}</b>${t.internal ? ' <span class="chip" style="background:#e0f2fe;color:#075985">Internal</span>' : ""}</td>
          <td>${escA(t.desc || "")}</td><td>${t.appId ? `<a href="?v=applicant&id=${encodeURIComponent(t.appId)}&tab=tasks">${escA(t.appName)}</a>` : escA(t.appName)}</td>
          <td>${escA(t.assignedTo)}</td><td>${amsFmtDate(t.due)}</td><td>${escA(t.status)}</td><td>${escA(t.priority || "—")}</td></tr>`).join("")
          || '<tr><td colspan="7"><div class="empty-state">No tasks.</div></td></tr>'}
      </tbody></table>` : ""}

      ${sec("evaluations") ? `<h2 class="report-sec"><span class="sec-no">${staffFocus ? "11" : "10"}</span> Appendix E — Evaluations (${evals.length})</h2>
      <table class="tbl report-tbl"><thead><tr>
        <th style="text-align:left">Applicant / Project</th><th style="text-align:left">Expert</th><th>Date</th><th>Score</th><th>Status</th><th style="text-align:left">Recommendation</th></tr></thead><tbody>
        ${evals.map(e => `<tr><td>${escA(e.appName)}</td><td>${escA(e.expert)}</td><td>${amsFmtDate(e.date)}</td>
          <td>${evalTotal(e) ?? "—"}</td><td>${escA(e.status)}</td><td>${escA(e.recommendation || "—")}</td></tr>`).join("")
          || '<tr><td colspan="6"><div class="empty-state">No evaluations yet.</div></td></tr>'}
      </tbody></table>` : ""}

      ${sec("portfolio") ? `<h2 class="report-sec"><span class="sec-no">${staffFocus ? "12" : "11"}</span> Portfolio Health (KPI)</h2>
      ${portfolioBlock(apps)}` : ""}

      ${sec("staff") ? `<h2 class="report-sec"><span class="sec-no">${staffFocus ? "13" : "12"}</span> Appendix F — Staff &amp; Access</h2>
      <table class="tbl report-tbl"><thead><tr><th style="text-align:left">Name</th><th style="text-align:left">Email</th><th>Job Title</th><th>Role</th><th>Status</th></tr></thead><tbody>
        ${staffList.map(s => `<tr><td><b>${escA(s.name)}</b></td><td>${escA(s.email)}</td><td>${escA(s.title || "—")}</td>
          <td>${escA(roles[s.role]?.label || s.role)}</td><td>${s.active ? "Active" : "Restricted"}</td></tr>`).join("")}
      </tbody></table>` : ""}

      <!-- signature block -->
      <div class="sig-block">
        <div class="sig-col"><div class="sig-line"></div><div class="sig-name">${escA(staff.name)}</div>
          <div class="sig-role">${escA(staff.title || roles[staff.role]?.label || staff.role)} — Prepared by</div>
          <div class="sig-date">Date: ______________</div></div>
        <div class="sig-col"><div class="sig-line"></div><div class="sig-name">&nbsp;</div>
          <div class="sig-role">Reviewed by</div><div class="sig-date">Date: ______________</div></div>
        <div class="sig-col"><div class="sig-line"></div><div class="sig-name">&nbsp;</div>
          <div class="sig-role">Approved by — ${escA(amsGetSettings().callName)}</div><div class="sig-date">Date: ______________</div></div>
      </div>

      <div class="report-foot">Kurdistan Innovation Institute · Confidential — for internal management use only<br>
        Generated ${amsFmtDate(today)} by ${escA(staff.name)} · Report No. KII-RPT-${today.replace(/-/g, "")}</div>
    </div>`;

  const rt = $ams("#rType", el);
  if (rt) rt.addEventListener("change", () => { P.set("r", rt.value); P.delete("id"); nav("?" + P.toString()); });

  $ams("#reportFilters", el).addEventListener("submit", (e) => {
    e.preventDefault();
    const f = e.target;
    nav(`?v=reports&r=${rt.value}&id=${encodeURIComponent(f.id.value)}` +
      `&from=${f.from.value}&to=${f.to.value}&sector=${encodeURIComponent(f.sector.value)}` +
      `&stage=${encodeURIComponent(f.stage.value)}&status=${encodeURIComponent(f.status.value)}` +
      `&assigned=${encodeURIComponent(f.assigned.value)}&scope=${f.scope.value}`);
  });

  $ams("#csvApps", el).addEventListener("click", () =>
    downloadCsv("kii-applicants.csv", [
      ["Applicant", "Project", "Sector", "Scope", "Stage", "Status", "Outcome", "Assigned To", "Applied", "Progress %", "Support Requested", "Approved $", "Spent $"],
      ...apps.map(a => [a.applicantName || "", a.name, a.sector, a.inScope ? "In scope" : "Out of scope",
        a.stage, a.status, a.outcome || "", a.assignedToName || "", amsFmtDate(a.appliedDate),
        a.progress, (a.supportRequested || []).join("; "), a.supportApproved || 0, a.spent || 0])]));

  $ams("#csvTasks", el).addEventListener("click", () =>
    downloadCsv("kii-tasks.csv", [
      ["Task", "Description", "Applicant", "Assigned To", "Due Date", "Status", "Priority"],
      ...tasks.map(t => [t.task, t.desc || "", t.appName, t.assignedTo, amsFmtDate(t.due), t.status, t.priority])]));

  $ams("#csvEvals", el).addEventListener("click", () => {
    const rows = apps.flatMap(a => (a.evaluations || []).map(e => [a.name, e.expert, amsFmtDate(e.date),
      evalTotal(e) ?? "", ...RUBRIC.map(c => e.scores?.[c.k] ?? ""), e.recommendation || "", e.status,
      [e.strengths, e.weaknesses, e.notes].filter(Boolean).join(" | ").replace(/\n/g, " ")]));
    downloadCsv("kii-evaluations.csv", [["Applicant", "Expert", "Date", "Total /100", ...RUBRIC.map(c => c.label + " (1-5)"),
      "Recommendation", "Status", "Comments"], ...rows]);
  });

  $ams("#csvMeet", el).addEventListener("click", () =>
    downloadCsv("kii-meetings.csv", [
      ["Applicant", "Meeting", "Date", "Time", "Location", "Status"],
      ...meetings.map(m => [m.appName, m.title, amsFmtDate(m.date), m.time || "", m.location || "", m.status])]));

  $ams("#csvPR", el).addEventListener("click", () =>
    downloadCsv("kii-procurement.csv", [
      ["PR #", "Applicant", "Title", "Amount", "Date", "Status"],
      ...prs.map(p => [p.number || p.id || "", p.appName, p.title || p.desc || "", p.amount || 0, amsFmtDate(p.date), p.status])]));
}

/* ============ VIEW: ENTITY RECORD REPORT (applicant / staff dossier) ============ */
function viewReportDoc(el) {
  const type = P.get("type") || "applicant";
  const id = P.get("id") || "";
  const today = new Date().toISOString().slice(0, 10);
  const roles = amsGetRoles();
  const docNo = `KII-RPT-${today.replace(/-/g, "")}-${amsUid("n").slice(-4).toUpperCase()}`;

  const back = `<div class="no-print" style="margin-bottom:12px"><a class="abtn ghost sm" href="javascript:history.back()">← Back</a>
    <button class="abtn sm" onclick="window.print()" style="margin-left:8px">${IC.report} Print / Save as PDF</button></div>`;

  /* ---------- helpers ---------- */
  const tbl = (heads, rows) => rows.length ? `<table class="tbl report-tbl"><thead><tr>${heads.map(h => `<th style="text-align:left">${h}</th>`).join("")}</tr></thead><tbody>${rows.join("")}</tbody></table>` : '<div class="empty-state">No records.</div>';
  const sec = (n, title, inner) => `<h2 class="report-sec"><span class="sec-no">${n}</span> ${title}</h2>${inner}`;
  const kv = (pairs) => `<table class="tbl report-tbl kv-tbl"><tbody>${pairs.map(([k, v]) => `<tr><td class="kv-k">${k}</td><td>${v || "—"}</td></tr>`).join("")}</tbody></table>`;
  const escV = v => escA(typeof v === "object" ? JSON.stringify(v) : String(v ?? ""));

  const head = (title, subtitle) => `
    <div class="report-sheet">
      <div class="letterhead">
        <img src="asset/kii_logocl.png" alt="KII" class="report-logo">
        <div class="letterhead-mid">
          <div class="lh-name">Kurdistan Innovation Institute</div>
          <div class="lh-line">Application Management System · ${title}</div>
          <div class="lh-line2">${escA(subtitle)}</div>
        </div>
        <table class="lh-meta"><tbody>
          <tr><td>Report No.</td><td>${docNo}</td></tr>
          <tr><td>Date</td><td>${amsFmtDate(today)}</td></tr>
          <tr><td>Prepared by</td><td>${escA(staff.name)}</td></tr>
          <tr><td>Classification</td><td><b>Confidential — Internal</b></td></tr>
        </tbody></table>
      </div>`;

  const foot = `
      <div class="sig-block">
        <div class="sig-col"><div class="sig-line"></div><div class="sig-name">${escA(staff.name)}</div>
          <div class="sig-role">${escA(staff.title || roles[staff.role]?.label || staff.role)} — Prepared by</div>
          <div class="sig-date">Date: ______________</div></div>
        <div class="sig-col"><div class="sig-line"></div><div class="sig-name">&nbsp;</div>
          <div class="sig-role">Reviewed by</div><div class="sig-date">Date: ______________</div></div>
        <div class="sig-col"><div class="sig-line"></div><div class="sig-name">&nbsp;</div>
          <div class="sig-role">Approved by — KII</div><div class="sig-date">Date: ______________</div></div>
      </div>
      <div class="report-foot">Kurdistan Innovation Institute · Confidential — for internal management use only<br>
        Generated ${amsFmtDate(today)} by ${escA(staff.name)} · ${docNo}</div>
    </div>`;

  /* ================= APPLICANT DOSSIER ================= */
  if (type === "applicant") {
    const a = amsGetApplicant(id);
    if (!a) { el.innerHTML = back + '<div class="ams-card">Record not found.</div>'; return; }
    const p = a.applicantInfo || a.personal || {};
    const chat = amsGetChat(a.id);
    const evalRows = (a.evaluations || []).map(e => `<tr><td>${escA(e.expert)}</td><td>${amsFmtDate(e.date)}</td>
      <td>${evalTotal(e) ?? "—"}</td><td>${escA(e.status)}</td><td>${escA(e.recommendation || "—")}</td>
      <td class="sub2">${escA([e.strengths, e.weaknesses, e.notes].filter(Boolean).join(" | ").slice(0, 300))}</td></tr>`);
    const taskRows = (a.tasks || []).map(t => `<tr><td><b>${escA(t.task)}</b></td><td>${escA(t.assignedTo)}</td>
      <td>${amsFmtDate(t.due)}</td><td>${escA(t.status)}</td><td>${escA(t.priority || "—")}</td>
      <td class="sub2">${escA(t.desc || "")}${t.response ? " · applicant responded " + amsFmtDate(t.response.date) : ""}</td></tr>`);
    const meetRows = (a.meetings || []).map(m => `<tr><td>${escA(m.title)}</td><td>${amsFmtDate(m.date)}</td>
      <td>${escA(m.time || "—")}</td><td>${escA(m.location || "—")}</td><td>${escA(m.status)}</td></tr>`);
    const prRows = (a.procurement || []).map(pr => `<tr><td>${escA(pr.number || pr.id || "—")}</td><td>${escA(pr.title || pr.desc || "—")}</td>
      <td>${pr.amount ? amsMoney(pr.amount) : "—"}</td><td>${amsFmtDate(pr.date)}</td><td>${escA(pr.status)}</td></tr>`);
    const actRows = (a.activities || []).slice(0, 60).map(x => `<tr><td>${amsFmtDateTime ? amsFmtDateTime(x.date) : amsFmtDate(x.date)}</td>
      <td>${escA(x.title)}</td><td class="sub2">${escA(x.desc || "")}</td><td>${escA(x.by || "—")}</td></tr>`);
    const decRows = (a.decisions || []).map(d => `<tr><td>${amsFmtDate(d.date)}</td><td>${escA(d.title || d.decision || d.type || "Decision")}</td>
      <td class="sub2">${escA(d.note || d.reason || d.desc || "")}</td><td>${escA(d.by || "—")}</td></tr>`);
    const uploadRows = (a.uploads || []).map(u => `<tr><td>${escA(u.name)}</td><td>${escA(u.field || u._key || "—")}</td>
      <td class="sub2">${fmtBytes(u.size)}</td><td>${u.fileId ? `<a href="#" class="view-upload" data-fid="${escA(u.fileId)}" data-name="${escA(u.name)}">Open</a>` : "—"}</td></tr>`);

    /* application answers — sectioned, using field labels where known */
    const appSections = Object.entries(a.application || {}).map(([secKey, fields]) => {
      if (!fields || typeof fields !== "object") return "";
      const rows = Object.entries(fields).filter(([, v]) => v !== "" && v != null && !(Array.isArray(v) && !v.length))
        .map(([fk, v]) => `<tr><td class="kv-k">${escA(FIELD_LABELS[fk] || fk.replace(/([A-Z])/g, " $1").replace(/^./, c => c.toUpperCase()))}</td>
          <td>${escA(Array.isArray(v) ? v.join(", ") : typeof v === "object" ? JSON.stringify(v) : v)}</td></tr>`);
      if (!rows.length) return "";
      return `<h3 class="app-sec-h">${escA(APP_SEC_LABELS[secKey] || secKey.replace(/([A-Z])/g, " $1").replace(/^./, c => c.toUpperCase()))}</h3>
        <table class="tbl report-tbl"><tbody>${rows.join("")}</tbody></table>`;
    }).join("");

    el.innerHTML = back + head("Applicant Dossier", `${a.name} — ${a.applicantName || ""}`) + `
      ${sec(1, "Applicant Profile", `<div style="display:flex;gap:22px;align-items:flex-start">
        ${p.photoFileId ? `<img class="dossier-photo" data-photo="${escA(p.photoFileId)}" alt="photo">` : ""}
        ${kv([
          ["Full name", escA(a.applicantName || p.fullName || p.name || "—")],
          ["Email", escA(p.email || a.applicantEmail || a.portalData?.email || "—")],
          ["Phone", escA(p.phone || "—")],
          ["Date of birth", escA(p.dob || p.dateOfBirth || "—")],
          ["Nationality", escA(p.nationality || p.country || "—")],
          ["Location", escA(a.location || [p.city, p.country].filter(Boolean).join(", ") || "—")],
          ["Applicant code", escA(a.code || a.applicantCode || "—")],
        ])}</div>`)}

      ${sec(2, "Application Overview", kv([
        ["Project", escA(a.name)], ["Sector", escA(a.sector || "—")], ["Stage", escA(a.stage)],
        ["Status", escA(a.status)], ["Outcome", escA(a.outcome || "—")],
        ["Scope", a.inScope === false ? "Out of scope" : "In scope"],
        ["Applied", amsFmtDate(a.appliedDate)], ["Last activity", amsFmtDate(a.lastActivity)],
        ["Progress", (a.progress ?? 0) + "%"], ["Assigned to", escA(a.assignedToName || "Unassigned")],
        ["Support approved", a.supportApproved ? amsMoney(a.supportApproved) : "—"],
        ["Spent", a.spent ? amsMoney(a.spent) : "—"],
      ]))}

      ${sec(3, "Application Answers — Complete Record", `<div class="app-dossier">${appSections || '<div class="empty-state">No application data.</div>'}</div>`)}

      ${sec(4, `Documents & Uploads (${(a.uploads || []).length})`, tbl(["File", "Field", "Size", ""], uploadRows))}
      ${sec(5, `Tasks & Follow-up (${(a.tasks || []).length})`, tbl(["Task", "Assigned To", "Due", "Status", "Priority", "Notes"], taskRows))}
      ${sec(6, `Meetings (${(a.meetings || []).length})`, tbl(["Meeting", "Date", "Time", "Location", "Status"], meetRows))}
      ${sec(7, `Expert Evaluations (${(a.evaluations || []).length})`, tbl(["Expert", "Date", "Score", "Status", "Recommendation", "Comments"], evalRows))}
      ${sec(8, "Financial Support & Procurement", kv([
        ["Support requested", (a.supportRequested || []).join(", ") || "—"],
        ["Approved", a.supportApproved ? amsMoney(a.supportApproved) : "—"],
        ["Spent", a.spent ? amsMoney(a.spent) : "—"],
      ]) + `<h3 class="app-sec-h">Purchase Requests (${(a.procurement || []).length})</h3>` +
        tbl(["PR #", "Title", "Amount", "Date", "Status"], prRows))}
      ${sec(9, `Decisions (${(a.decisions || []).length})`, tbl(["Date", "Decision", "Detail", "By"], decRows))}
      ${sec(10, `Activity Log — last ${(a.activities || []).length > 60 ? 60 : (a.activities || []).length} entries`, tbl(["Date", "Action", "Detail", "By"], actRows))}
      ${sec(11, `Communication — ${chat.length} message(s) exchanged with the team`, chat.length ? tbl(["From", "Date", "Message"], chat.slice(-40).map(m => `<tr><td>${escA(m.from === "staff" ? (m.name || "KII") : (m.name || "Applicant"))}</td><td>${amsFmtDateTime(m.date)}</td><td class="sub2">${escA(m.text || "(attachment)")}</td></tr>`)) : '<div class="empty-state">No messages.</div>')}
      ${foot}`;

    $$ams(".dossier-photo[data-photo]", el).forEach(img =>
      KII.getFile(img.dataset.photo).then(f => { if (f) img.src = URL.createObjectURL(f); }).catch(() => { }));
    bindUploadViewers(el);
    return;
  }

  /* ================= STAFF DOSSIER ================= */
  if (type === "staff") {
    const s = amsGetStaff().find(x => x.id === id);
    if (!s) { el.innerHTML = back + '<div class="ams-card">Staff record not found.</div>'; return; }
    const myApps = amsGetApplicants().filter(a => a.assignedToName === s.name);
    const myTasks = allTasks().filter(t => t.assignedTo === s.name || t.by === s.name || t.byId === s.id);
    const myDone = myTasks.filter(t => t.status === "Completed");
    const myOpen = myTasks.filter(t => t.status !== "Completed");
    const myOverdue = myOpen.filter(t => daysUntil(t.due) < 0);
    const myEvals = amsGetApplicants().flatMap(a => (a.evaluations || []).filter(e => e.expert === s.name || e.by === s.name)
      .map(e => ({ ...e, appName: a.name })));
    const myMeetings = amsGetApplicants().flatMap(a => (a.meetings || []).filter(m => m.by === s.name || m.owner === s.name)
      .map(m => ({ ...m, appName: a.name })));
    const myActs = amsGetApplicants().flatMap(a => (a.activities || []).filter(x => x.by === s.name || x.byId === s.id)
      .map(x => ({ ...x, appName: a.name }))).sort((x, y) => new Date(y.date) - new Date(x.date)).slice(0, 80);
    const tRows = myTasks.map(t => `<tr><td><b>${escA(t.task)}</b>${t.internal ? ' <span class="chip" style="background:#e0f2fe;color:#075985">Internal</span>' : ""}</td>
      <td>${t.appId ? `<a href="?v=applicant&id=${encodeURIComponent(t.appId)}">${escA(t.appName)}</a>` : escA(t.appName)}</td>
      <td>${amsFmtDate(t.due)}</td><td>${escA(t.status)}</td><td>${escA(t.priority || "—")}</td>
      <td>${t.assignedTo === s.name ? "Assigned" : "Created"}</td></tr>`);

    el.innerHTML = back + head("Staff Member Dossier", `${s.name} — ${s.title || roles[s.role]?.label || s.role}`) + `
      ${sec(1, "Account & Access", `<div style="display:flex;gap:22px;align-items:flex-start">
        <div class="avatar-lg">${escA(s.name.split(" ").map(w => w[0]).slice(0, 2).join("").toUpperCase())}</div>
        ${kv([
          ["Full name", escA(s.name)], ["Email", escA(s.email)], ["Job title", escA(s.title || "—")],
          ["Role", escA(roles[s.role]?.label || s.role)], ["Status", s.active ? "Active" : "Restricted — cannot sign in"],
          ["Created", s.createdAt ? amsFmtDate(s.createdAt) : "—"],
          ["Must change password", s.mustChangePassword ? "Yes (first sign-in)" : "No"],
        ])}</div>`)}
      ${sec(2, `Permissions (${(s.perms || []).length})`, `<div class="perm-chips">${(s.perms || []).map(p => `<span class="chip chip-active">${escA(PERM_LABELS[p] || p)}</span>`).join("") || '<span class="sub2">No explicit permissions</span>'}</div>`)}
      ${sec(3, `Workload — ${myTasks.length} task(s)`, kv([
        ["Completed", String(myDone.length)], ["Open / in progress", String(myOpen.length)],
        ["Overdue", String(myOverdue.length)], ["Completion rate", myTasks.length ? Math.round(myDone.length / myTasks.length * 100) + "%" : "—"],
      ]) + `<h3 class="app-sec-h">All Tasks</h3>` + tbl(["Task", "Applicant", "Due", "Status", "Priority", "Role"], tRows))}
      ${sec(4, `Evaluations Submitted (${myEvals.length})`, tbl(["Applicant / Project", "Date", "Score", "Status", "Recommendation"], myEvals.map(e => `<tr><td>${escA(e.appName)}</td><td>${amsFmtDate(e.date)}</td><td>${evalTotal(e) ?? "—"}</td><td>${escA(e.status)}</td><td>${escA(e.recommendation || "—")}</td></tr>`)))}
      ${sec(5, `Meetings Conducted (${myMeetings.length})`, tbl(["Applicant / Project", "Meeting", "Date", "Time", "Status"], myMeetings.map(m => `<tr><td>${escA(m.appName)}</td><td>${escA(m.title)}</td><td>${amsFmtDate(m.date)}</td><td>${escA(m.time || "—")}</td><td>${escA(m.status)}</td></tr>`)))}
      ${sec(6, `Applicants Handled (${myApps.length})`, tbl(["Applicant", "Project", "Sector", "Stage", "Status", "Progress"], myApps.map(a => `<tr><td><b>${escA(a.applicantName || "—")}</b></td><td><a href="?v=applicant&id=${encodeURIComponent(a.id)}">${escA(a.name)}</a></td><td>${escA(a.sector || "—")}</td><td>${escA(a.stage)}</td><td>${escA(a.status)}</td><td>${a.progress ?? 0}%</td></tr>`)))}
      ${sec(7, `Activity Log — last ${myActs.length} recorded actions`, tbl(["Date", "Applicant / Project", "Action", "Detail"], myActs.map(x => `<tr><td>${amsFmtDateTime ? amsFmtDateTime(x.date) : amsFmtDate(x.date)}</td><td>${escA(x.appName || "—")}</td><td>${escA(x.title)}</td><td class="sub2">${escA(x.desc || "")}</td></tr>`)))}
      ${foot}`;
    return;
  }

  /* single-record dossiers: task / meeting / procurement / evaluation */
  if (["task", "meeting", "procurement", "evaluation"].includes(type)) {
    let rec = null, ctx = null;
    for (const a of amsGetApplicants()) {
      if (type === "task" && (a.tasks || []).some(t => t.id === id)) { rec = a.tasks.find(t => t.id === id); ctx = a; break; }
      if (type === "meeting" && (a.meetings || []).some(m => m.id === id)) { rec = a.meetings.find(m => m.id === id); ctx = a; break; }
      if (type === "procurement" && (a.procurement || []).some(p => (p.id === id || p.number === id))) { rec = a.procurement.find(p => p.id === id || p.number === id); ctx = a; break; }
      if (type === "evaluation" && (a.evaluations || []).some(e => e.id === id)) { rec = a.evaluations.find(e => e.id === id); ctx = a; break; }
      if (type === "task" && (amsGetInternalTasks() || []).some(t => t.id === id)) {
        rec = { ...amsGetInternalTasks().find(t => t.id === id), internal: true, appName: "Internal" }; break;
      }
    }
    if (!rec) { el.innerHTML = back + '<div class="ams-card">Record not found.</div>'; return; }
    const labels = { task: "Task Record", meeting: "Meeting Record", procurement: "Purchase Request Record", evaluation: "Evaluation Record" };
    let body = "";
    if (type === "task") body = kv([["Task", escA(rec.task)], ["Description", escA(rec.desc || "—")],
      ["Assigned to", escA(rec.assignedTo)], ["Assigned by", escA(rec.by || "—")], ["Due", amsFmtDate(rec.due)],
      ["Status", escA(rec.status)], ["Priority", escA(rec.priority || "—")], ["Applicant", escA(rec.appName || "Internal")],
      ["Created", rec.created ? amsFmtDateTime(rec.created) : "—"], ["Completed", rec.doneAt ? amsFmtDateTime(rec.doneAt) : "—"]])
      + ((rec.links || []).length ? `<h3 class="app-sec-h">Links</h3><ul>${rec.links.map(l => `<li><a href="${escA(l)}" target="_blank">${escA(l)}</a></li>`).join("")}</ul>` : "")
      + ((rec.attachments || []).length ? `<h3 class="app-sec-h">Attachments</h3><ul>${rec.attachments.map(f => `<li>${f.fileId ? `<a href="#" class="view-upload" data-fid="${escA(f.fileId)}" data-name="${escA(f.name)}">${escA(f.name)}</a>` : escA(f.name)}</li>`).join("")}</ul>` : "")
      + ((rec.updates || []).length ? `<h3 class="app-sec-h">Updates (${rec.updates.length})</h3>` + tbl(["Date", "By", "Note"], rec.updates.map(u => `<tr><td>${amsFmtDateTime(u.date)}</td><td>${escA(u.by)}</td><td class="sub2">${escA(u.note || "")}</td></tr>`)) : "");
    if (type === "meeting") body = kv([["Meeting", escA(rec.title)], ["Date", amsFmtDate(rec.date)], ["Time", escA(rec.time || "—")],
      ["Location", escA(rec.location || "—")], ["Status", escA(rec.status)], ["Applicant", escA(ctx ? ctx.name : "—")],
      ["Notes", escA(rec.notes || rec.desc || "—")]]);
    if (type === "procurement") body = kv([["PR #", escA(rec.number || rec.id || "—")], ["Title", escA(rec.title || rec.desc || "—")],
      ["Applicant", escA(ctx ? ctx.name : "—")], ["Amount", rec.amount ? amsMoney(rec.amount) : "—"],
      ["Date", amsFmtDate(rec.date)], ["Status", escA(rec.status)], ["Details", escA(rec.details || rec.note || "—")]]);
    if (type === "evaluation") body = kv([["Applicant", escA(ctx ? ctx.name : "—")], ["Expert", escA(rec.expert)],
      ["Date", amsFmtDate(rec.date)], ["Score", evalTotal(rec) ?? "—"], ["Status", escA(rec.status)],
      ["Recommendation", escA(rec.recommendation || "—")],
      ["Strengths", escA(rec.strengths || "—")], ["Weaknesses", escA(rec.weaknesses || "—")], ["Notes", escA(rec.notes || "—")]]);
    el.innerHTML = back + head(labels[type], ctx ? `${ctx.name} — ${ctx.applicantName || ""}` : "Internal record") + `
      ${sec(1, labels[type], `<div class="app-dossier">${body}</div>`)}
      ${ctx ? sec(2, "Related Applicant", `<div class="sub2"><a href="?v=applicant&id=${encodeURIComponent(ctx.id)}">Open full applicant record →</a></div>`) : ""}
      ${foot}`;
    bindUploadViewers(el);
    return;
  }

  el.innerHTML = back + '<div class="ams-card">Unknown report type.</div>';
}

/* ============ VIEW: DOCUMENTS (all) ============ */
function viewDocuments(el) {
  const apps = amsGetApplicants();
  const uploads = apps.flatMap(a => (a.uploads || []).map(u => ({ ...u, appId: a.id, appName: a.name, applicant: a.applicantName, date: a.appliedDate })));
  const rows = apps.flatMap(a => (a.documents || [])
    .map(d => ({ ...d, appId: a.id, appName: a.name })))
    .sort((x, y) => new Date(y.date) - new Date(x.date));
  el.innerHTML = `
    <div class="page-title">Documents</div>
    <div class="page-sub">Applicant uploads and staff documents across all applications</div>
    <div class="ams-card"><h3>Uploaded by Applicants (${uploads.length})</h3>
      <table class="tbl"><thead><tr>
      <th>Applicant</th><th>Project</th><th>Field</th><th>File</th><th>Size</th>
    </tr></thead><tbody>
    ${uploads.map(u => `<tr>
      <td><b>${escA(u.applicant || "—")}</b></td>
      <td><a href="?v=applicant&id=${encodeURIComponent(u.appId)}&tab=documents">${escA(u.appName)}</a></td>
      <td>${camelLbl(u._key)}</td>
      <td>${u.fileId ? `<a href="#" class="view-upload" data-fid="${escA(u.fileId)}" data-name="${escA(u.name)}">${escA(u.name)}</a>` : escA(u.name)}</td>
      <td class="sub2">${fmtBytes(u.size)}</td>
    </tr>`).join("") || '<tr><td colspan="5"><div class="empty-state">No applicant uploads yet.</div></td></tr>'}
    </tbody></table></div>
    <div class="ams-card"><h3>Staff Documents (${rows.length})</h3><table class="tbl"><thead><tr>
      <th>Document</th><th>Applicant</th><th>File</th><th>Date</th><th>Size</th>
    </tr></thead><tbody>
    ${rows.map(d => `<tr>
      <td><b>${escA(d.name)}</b></td><td><a href="?v=applicant&id=${encodeURIComponent(d.appId)}&tab=documents">${escA(d.appName)}</a></td>
      <td class="sub2">${escA(d.file)}</td><td>${amsFmtDate(d.date)}</td><td class="sub2">${escA(d.size || "—")}</td>
    </tr>`).join("") || '<tr><td colspan="5"><div class="empty-state">No staff documents.</div></td></tr>'}
    </tbody></table></div>`;
  bindUploadViewers(el);
}

/* ============ VIEW: TEAM & ROLES ============ */
function viewTeam(el) {
  const list = amsGetStaff();
  const roles = amsGetRoles();
  const roleEntries = Object.entries(roles);
  const customRoles = roleEntries.filter(([k]) => !ROLES[k]);
  const canEdit = (s) =>
    s.id !== staff.id &&
    (s.role !== "master_admin" || staff.role === "master_admin");

  el.innerHTML = `
    <div class="page-title">Team &amp; Roles</div>
    <div class="page-sub">Manage staff accounts, roles and permissions. Restricted staff cannot sign in.</div>

    <div class="ams-card"><h3>Add Staff Member</h3>
      <form id="addStaffForm" class="inline-form">
        <div class="grid-2">
          <div><label>Full Name</label><input name="name" required></div>
          <div><label>Email</label><input type="email" name="email" required></div>
          <div><label>Temporary password</label><input type="password" name="password" required minlength="8" autocomplete="new-password">
            <div class="sub2" style="margin-top:3px">The staff member must change it at first sign-in.</div></div>
          <div><label>Job Title</label><input name="title" placeholder="e.g. Technical Engineer"></div>
          <div><label>Role</label><select name="role">
            ${roleEntries.filter(([k]) => k !== "master_admin" || staff.role === "master_admin")
              .map(([k, r]) => `<option value="${k}">${r.label}</option>`).join("")}
          </select></div>
        </div>
        <button class="abtn sm" style="margin-top:10px">${IC.plus} Create Staff Account</button>
      </form>
    </div>

    <div class="ams-card"><h3>Access Control — Role Permission Matrix</h3>
      <div class="sub2" style="margin-bottom:10px">Choose what each role can do across the whole system. New staff get their role's permissions; you can also give individual staff personal overrides below.</div>
      <div style="overflow-x:auto"><table class="tbl acl-matrix"><thead><tr>
        <th style="text-align:left">Permission</th>
        ${roleEntries.map(([k, r]) => `<th>${escA(r.label)}${!ROLES[k] ? `<br><button class="abtn danger sm" data-roledel="${k}" style="margin-top:3px">Delete</button>` : k === "master_admin" ? '<br><small class="sub2">full access</small>' : ""}</th>`).join("")}
      </tr></thead><tbody>
      ${ALL_PERMS.map(p => `<tr>
        <td><b>${PERM_LABELS[p]}</b><div class="sub2">${p}</div></td>
        ${roleEntries.map(([k, r]) => `<td><input type="checkbox" data-roleperm="${k}|${p}"
          ${r.perms.includes(p) ? "checked" : ""} ${k === "master_admin" ? "disabled" : ""}></td>`).join("")}
      </tr>`).join("")}
      </tbody></table></div>
      <div style="margin-top:16px;border-top:1px solid #eef1f5;padding-top:14px">
        <h4 style="margin:0 0 8px">Create Custom Role</h4>
        <form id="newRoleForm" class="inline-form">
          <input name="rlabel" required placeholder="Role name — e.g. Finance Officer"
            style="padding:8px 12px;border:1px solid #d6dee6;border-radius:8px;min-width:240px">
          <div class="perm-grid" style="margin:10px 0">${ALL_PERMS.map(p =>
            `<label><input type="checkbox" name="rperm" value="${p}"> ${PERM_LABELS[p]}</label>`).join("")}</div>
          <button class="abtn sm">${IC.plus} Create Role</button>
        </form>
      </div>
    </div>

    ${staff.role === "master_admin" ? sectorEditorHtml() : ""}

    <div class="ams-card"><h3>Staff Members (${list.length})</h3>
      ${list.map(s => {
        const editable = canEdit(s);
        return `<div class="team-row">
          <div class="head">
            <span class="avatar-sm">${escA(s.name.split(" ").map(w => w[0]).slice(0, 2).join("").toUpperCase())}</span>
            <div style="flex:1;min-width:180px">
              <b>${escA(s.name)}</b> ${!s.active ? '<span class="chip chip-rejected">Restricted</span>' : '<span class="chip chip-active">Active</span>'}
              <div class="sub2">${escA(s.email)} · ${escA(s.title || ROLES[s.role]?.label || s.role)}</div>
            </div>
            ${editable ? `
              <select data-role-id="${s.id}">
                ${roleEntries.filter(([k]) => k !== "master_admin" || staff.role === "master_admin")
                  .map(([k, r]) => `<option value="${k}" ${s.role === k ? "selected" : ""}>${r.label}</option>`).join("")}
              </select>
              <button class="abtn ${s.active ? "danger" : ""} sm" data-toggle="${s.id}">
                ${s.active ? "Restrict" : "Activate"}</button>
              <button class="abtn ghost sm" data-perms="${s.id}">Permissions</button>
              <a class="abtn ghost sm" href="?v=reportdoc&type=staff&id=${encodeURIComponent(s.id)}" target="_blank">Report</a>`
            : '<span class="sub2">(cannot edit)</span>'}
          </div>
          <div class="perm-grid hidden" id="perms-${s.id}">
            ${ALL_PERMS.map(p => `<label><input type="checkbox" data-staff="${s.id}" value="${p}"
              ${(s.perms || []).includes(p) ? "checked" : ""} ${editable ? "" : "disabled"}> ${PERM_LABELS[p]}</label>`).join("")}
          </div>
        </div>`;
      }).join("")}
    </div>`;

  $ams("#addStaffForm", el).addEventListener("submit", (e) => {
    e.preventDefault();
    const f = e.target;
    if (amsFindStaff(f.email.value.trim())) { alert("A staff account with this email already exists."); return; }
    const role = f.role.value;
    if (f.password.value.length < 8) { alert("Temporary password must be at least 8 characters."); return; }
    amsAddStaff({
      id: amsUid("st"), name: f.name.value.trim(), email: f.email.value.trim(),
      ...amsPwFields(f.password.value), mustChangePassword: true,
      role, title: f.title.value.trim() || roles[role].label,
      active: true, perms: [...roles[role].perms], createdAt: new Date().toISOString(),
    });
    amsAudit(staff.name, "Staff account created", `${f.name.value.trim()} <${f.email.value.trim()}> as ${roles[role].label}`);
    route();
  });

  $$ams("[data-toggle]", el).forEach(b => b.addEventListener("click", () => {
    const s = amsGetStaff().find(x => x.id === b.dataset.toggle);
    if (!s) return;
    if (s.active && !confirm(`Restrict ${s.name}? They will not be able to sign in.`)) return;
    amsUpdateStaff(s.id, { active: !s.active });
    amsAudit(staff.name, s.active ? "Staff restricted" : "Staff activated", s.name);
    route();
  }));

  $$ams("[data-perms]", el).forEach(b => b.addEventListener("click", () =>
    $ams("#perms-" + b.dataset.perms, el).classList.toggle("hidden")));

  $$ams("[data-role-id]", el).forEach(sel => sel.addEventListener("change", () => {
    const s = amsGetStaff().find(x => x.id === sel.dataset.roleId);
    if (!s) return;
    const rr = amsGetRoles();
    const title = !s.title || s.title === rr[s.role]?.label ? rr[sel.value].label : s.title;
    amsUpdateStaff(s.id, { role: sel.value, title, perms: [...rr[sel.value].perms] });
    amsAudit(staff.name, "Role changed", `${s.name}: ${amsGetRoles()[s.role]?.label || s.role} → ${amsGetRoles()[sel.value].label}`);
    route();
  }));

  $$ams('input[type="checkbox"][data-staff]', el).forEach(cb => cb.addEventListener("change", () => {
    const s = amsGetStaff().find(x => x.id === cb.dataset.staff);
    if (!s) return;
    const perms = new Set(s.perms || []);
    cb.checked ? perms.add(cb.value) : perms.delete(cb.value);
    amsUpdateStaff(s.id, { perms: [...perms] });
    amsAudit(staff.name, cb.checked ? "Permission granted" : "Permission revoked", `${s.name}: ${PERM_LABELS[cb.value]}`);
  }));

  /* ACL: role matrix + custom roles */
  $$ams("[data-roleperm]", el).forEach(cb => cb.addEventListener("change", () => {
    const [roleId, perm] = cb.dataset.roleperm.split("|");
    const def = amsGetRoles()[roleId];
    if (!def) return;
    const perms = cb.checked ? [...new Set([...def.perms, perm])] : def.perms.filter(p => p !== perm);
    amsSaveRole(roleId, { label: def.label, perms });
    amsAudit(staff.name, cb.checked ? "Role permission granted" : "Role permission revoked",
      `${def.label}: ${PERM_LABELS[perm]}`);
    nav("?v=team");
  }));
  $$ams("[data-roledel]", el).forEach(b => b.addEventListener("click", () => {
    const users = amsGetStaff().filter(s => s.role === b.dataset.roledel);
    if (users.length) { alert(`Cannot delete — ${users.length} staff member(s) still have this role.`); return; }
    if (!confirm(`Delete role "${amsGetRoles()[b.dataset.roledel]?.label}"?`)) return;
    amsDeleteRole(b.dataset.roledel);
    amsAudit(staff.name, "Custom role deleted", b.dataset.roledel);
    nav("?v=team");
  }));
  $ams("#newRoleForm", el)?.addEventListener("submit", (e) => {
    e.preventDefault();
    const f = e.target;
    const perms = [...f.querySelectorAll('input[name="rperm"]:checked')].map(c => c.value);
    if (!perms.length) { alert("Select at least one permission for the role."); return; }
    const id = "role_" + amsUid("r");
    amsSaveRole(id, { label: f.rlabel.value.trim(), perms });
    amsAudit(staff.name, "Custom role created", `${f.rlabel.value.trim()} (${perms.length} permissions)`);
    nav("?v=team");
  });
  if (staff.role === "master_admin") bindSectorEditor(el);
}

/* Sector catalogue (Master Admin only). Applicants see these sectors and sub-sectors in Project Information;
   "Other" is always offered automatically. */
function sectorEditorHtml() {
  const sectors = KII.sectorCatalogue();
  return `<div class="ams-card" id="sectorEditor"><h3>Application Sectors &amp; Sub-sectors</h3>
    <div class="sub2" style="margin-bottom:10px">Applicants choose from this list in the “Project Information” step. “Other (specify)” is always available. Changes apply to new and in-progress applications immediately; submitted applications keep their recorded sector.</div>
    ${sectors.map((s, i) => `<div class="team-row" data-sector="${i}">
      <div class="head">
        <b style="flex:1;min-width:160px">${escA(s.name)}</b>
        <span class="sub2">${s.subSectors.length} sub-sector(s)</span>
        <button class="abtn ghost sm" data-sector-sub="${i}">Sub-sectors</button>
        <button class="abtn danger sm" data-sector-remove="${i}">Remove sector</button>
      </div>
      <div class="perm-grid hidden" id="subsectors-${i}" style="display:block">
        ${s.subSectors.map((sub, j) => `<div style="display:flex;gap:8px;align-items:center;margin:4px 0">
          <span style="flex:1">${escA(sub)}</span>
          <button class="abtn ghost sm" data-sub-remove="${i}:${j}" aria-label="Remove ${escA(sub)}">Remove</button></div>`).join("") || '<div class="sub2">No sub-sectors yet.</div>'}
        <form class="inline-form" data-sub-add="${i}" style="display:flex;gap:8px;margin-top:8px">
          <input name="sub" placeholder="New sub-sector name" required maxlength="80" style="flex:1">
          <button class="abtn sm">${IC.plus} Add sub-sector</button>
        </form>
      </div>
    </div>`).join("")}
    <form id="addSectorForm" class="inline-form" style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap">
      <input name="name" placeholder="New sector name" required maxlength="80" style="flex:1;min-width:200px">
      <button class="abtn sm">${IC.plus} Add sector</button>
      <button type="button" class="abtn ghost sm" id="resetSectors">Restore default sectors</button>
    </form>
  </div>`;
}
function bindSectorEditor(el) {
  const save = (sectors, action, detail) => {
    amsSaveSettings({ ...amsGetSettings(), sectors });
    amsAudit(staff.name, action, detail);
    const page = el.closest("#amsContent") || el;
    viewTeam(page);
  };
  const current = () => KII.sectorCatalogue();
  const clean = value => String(value || "").replace(/\s+/g, " ").trim();
  $ams("#addSectorForm", el)?.addEventListener("submit", e => {
    e.preventDefault();
    const name = clean(e.target.name.value), sectors = current();
    if (!name || name.toLowerCase() === "other") return alert("Enter a sector name other than “Other”.");
    if (sectors.some(s => s.name.toLowerCase() === name.toLowerCase())) return alert("This sector already exists.");
    save([...sectors, { name, subSectors: [] }], "Sector added", name);
  });
  $ams("#resetSectors", el)?.addEventListener("click", () => {
    if (!confirm("Restore the default KII sectors and sub-sectors? Your custom list will be replaced.")) return;
    save(JSON.parse(JSON.stringify(KII.DEFAULT_SECTORS)), "Sectors reset to defaults", "");
  });
  $$ams("[data-sector-remove]", el).forEach(b => b.addEventListener("click", () => {
    const sectors = current(), s = sectors[+b.dataset.sectorRemove];
    if (!s || !confirm(`Remove the sector “${s.name}” and its sub-sectors from the application form?`)) return;
    save(sectors.filter((_, i) => i !== +b.dataset.sectorRemove), "Sector removed", s.name);
  }));
  $$ams("[data-sector-sub]", el).forEach(b => b.addEventListener("click", () =>
    $ams("#subsectors-" + b.dataset.sectorSub, el).classList.toggle("hidden")));
  $$ams("[data-sub-remove]", el).forEach(b => b.addEventListener("click", () => {
    const [i, j] = b.dataset.subRemove.split(":").map(Number), sectors = current();
    const removed = sectors[i]?.subSectors[j];
    if (removed == null) return;
    sectors[i].subSectors.splice(j, 1);
    save(sectors, "Sub-sector removed", `${sectors[i].name}: ${removed}`);
  }));
  $$ams("[data-sub-add]", el).forEach(f => f.addEventListener("submit", e => {
    e.preventDefault();
    const i = +f.dataset.subAdd, sectors = current(), sub = clean(f.sub.value);
    if (!sub || sub.toLowerCase() === "other") return alert("Enter a sub-sector name other than “Other”.");
    if (sectors[i].subSectors.some(x => x.toLowerCase() === sub.toLowerCase())) return alert("This sub-sector already exists.");
    sectors[i].subSectors.push(sub);
    save(sectors, "Sub-sector added", `${sectors[i].name}: ${sub}`);
  }));
}

/* ============ VIEW: SETTINGS ============ */
function viewSettings(el) {
  el.innerHTML = `
    <div class="page-title">Settings</div>
    <div class="page-sub">Your staff profile</div>
    ${staff.mustChangePassword ? `<div class="ams-card" style="border-left:4px solid #dc2626;background:#fef2f2">
      <b>Please set a new password.</b> For security, you must replace the temporary password before using the system.</div>` : ""}
    <div class="grid-2col">
      <div class="ams-card"><h3>Profile</h3>
        <table class="tbl"><tbody>
          <tr><td>Name</td><td><b>${escA(staff.name)}</b></td></tr>
          <tr><td>Email</td><td>${escA(staff.email)}</td></tr>
          <tr><td>Role</td><td>${escA(ROLES[staff.role]?.label || staff.role)}</td></tr>
          <tr><td>Title</td><td>${escA(staff.title || "—")}</td></tr>
        </tbody></table>
      </div>
      <div class="ams-card"><h3>Change Password</h3>
        <form id="pwForm" class="inline-form" style="margin:0">
          <div><label>New password</label><input type="password" name="pw" minlength="8" required autocomplete="new-password"></div>
          <div><label>Confirm</label><input type="password" name="pw2" required></div>
          <button class="abtn sm" style="margin-top:10px">Update Password</button>
        </form>
      </div>
    </div>
    <div class="ams-card"><h3>Your Permissions</h3>
      <div class="perm-grid">${(staff.perms || []).map(p => `<label>✓ ${PERM_LABELS[p] || p}</label>`).join("") || '<div class="empty-state">No permissions.</div>'}</div>
    </div>
    ${can("manage_staff") ? `<div class="ams-card"><h3>System Settings</h3>
      <form id="sysForm" class="inline-form" style="margin:0">
        <div class="grid-2">
          <div><label>Inactive applicant threshold (days)</label>
            <input type="number" name="inactiveDays" min="7" max="365" value="${amsGetSettings().inactiveDays}">
            <div class="sub2" style="margin-top:3px">Applicants with no activity for this many days are flagged as inactive and trigger alerts/reminders.</div></div>
          <div><label>Automatic reminders</label>
            <select name="reminders">
              <option value="true" ${amsGetSettings().reminders ? "selected" : ""}>Enabled</option>
              <option value="false" ${!amsGetSettings().reminders ? "selected" : ""}>Disabled</option></select></div>
          <div><label>Program call / cohort name</label>
            <input name="callName" value="${escA(amsGetSettings().callName)}" placeholder="e.g. KII Innovation Program 2026 Cohort">
            <div class="sub2" style="margin-top:3px">Shown to applicants on their dashboard.</div></div>
          <div><label>Application deadline</label>
            <input type="date" name="deadline" value="${escA(amsGetSettings().deadline)}">
            <div class="sub2" style="margin-top:3px">Leave empty for rolling applications. After this date applicants cannot submit.</div></div>
          <div><label>Blind review for expert evaluators</label>
            <select name="blindReview">
              <option value="false" ${!amsGetSettings().blindReview ? "selected" : ""}>Off — experts see applicant identity</option>
              <option value="true" ${amsGetSettings().blindReview ? "selected" : ""}>On — hide name, CV, photo, video &amp; references</option></select>
            <div class="sub2" style="margin-top:3px">Reduces bias. Applies to staff with the Evaluator / Expert role.</div></div>
        </div>
        <button class="abtn sm" style="margin-top:10px">Save Settings</button>
      </form></div>
      <div class="ams-card"><h3>System Audit Log <span class="sub2">(sign-ins, staff, roles, permissions, settings)</span></h3>
        <table class="tbl"><thead><tr><th>Date</th><th>By</th><th>Action</th><th>Detail</th></tr></thead><tbody>
        ${amsGetAudit().slice(0, 100).map(x => `<tr><td class="sub2">${amsFmtDateTime(x.date)}</td><td>${escA(x.by)}</td>
          <td><b>${escA(x.action)}</b></td><td class="sub2">${escA(x.detail)}</td></tr>`).join("")
          || '<tr><td colspan="4"><div class="empty-state">No entries yet.</div></td></tr>'}
        </tbody></table>
      </div>` : ""}`;
  $ams("#pwForm", el).addEventListener("submit", (e) => {
    e.preventDefault();
    const f = e.target;
    if (f.pw.value !== f.pw2.value) { alert("Passwords do not match."); return; }
    if (f.pw.value.length < 8 || !/[A-Za-z]/.test(f.pw.value) || !/\d/.test(f.pw.value)) { alert("Use at least 8 characters with letters and numbers."); return; }
    if (KII.checkPassword(staff, f.pw.value)) { alert("Please choose a password different from the current one."); return; }
    amsUpdateStaff(staff.id, { ...amsPwFields(f.pw.value), password: undefined, mustChangePassword: false });
    amsAudit(staff.name, "Password changed", "");
    alert("Password updated.");
    nav("?v=settings");
  });
  const sys = $ams("#sysForm", el);
  if (sys) sys.addEventListener("submit", (e) => {
    e.preventDefault();
    const next = { ...amsGetSettings(), inactiveDays: +sys.inactiveDays.value, reminders: sys.reminders.value === "true",
      callName: sys.callName.value.trim() || AMS_DEFAULT_SETTINGS.callName, deadline: sys.deadline.value,
      blindReview: sys.blindReview.value === "true" };
    amsSaveSettings(next);
    amsAudit(staff.name, "System settings changed",
      `Inactive ${next.inactiveDays}d · call "${next.callName}" · deadline ${next.deadline || "rolling"} · blind review ${next.blindReview ? "on" : "off"}`);
    alert("Settings saved.");
    route();
  });
}

/* ---------- application form builder (Master Admin) ---------- */
const FB_TYPES = {
  text: "Short answer", textarea: "Paragraph", number: "Number", date: "Date", url: "Website link",
  select: "Dropdown (one choice)", checks: "Checkboxes (multiple choices)", yesno: "Yes / No", file: "File upload",
};
const FB_BUILTIN_TYPES = {
  text: "Short answer", textarea: "Paragraph", number: "Number", date: "Date", dob: "Date of birth", url: "Website link",
  select: "Dropdown", search: "Searchable list", checks: "Checkboxes", checkbox: "Tick box", file: "File upload",
  repeat: "Table (repeating rows)", multitext: "List of answers", email: "Email", phone: "Phone", digits: "Number (digits)", month: "Month",
};
/* questions other logic depends on (identity, routing, ID code, budget) cannot be hidden */
const FB_LOCKED = new Set(["instruction.agreeApp", "personal.firstName",
  "personal.secondName", "personal.thirdName", "personal.email", "personal.country", "personal.city", "personal.phoneCode",
  "personal.phone", "innovation.title", "innovation.sector", "innovation.subSector", "support.supportTypes",
  "support.reqCurrency", "support.requirements"]);
function fbSchema() {
  let live = null;
  try { live = KII.formSchemaInfo(); } catch { }
  return (live && live.length ? live : window.KII_FORM_SCHEMA) || [];
}
function viewFormBuilder(el) {
  const sections = fbSchema();
  if (!sections.length) { el.innerHTML = `<div class="ams-card">The form definition could not be loaded. Please reload the page.</div>`; return; }
  const cfg = KII.formCustom();
  cfg.custom ||= []; cfg.hidden ||= []; cfg.overrides ||= {}; cfg.deleted ||= [];
  /* two-step confirmation before any form change is saved (required for every action) */
  const sure = what => confirm(`Are you sure you want to ${what}?`) &&
    confirm(`Please confirm once more — this changes the live application form for every applicant. Continue?`);
  const deletedSet = new Set(cfg.deleted);
  const sec = sections.find(s => s.id === P.get("sec")) || sections[0];
  const editKey = P.get("edit");
  const save = (action, detail) => {
    cfg.updatedAt = new Date().toISOString(); cfg.updatedBy = staff.name;
    KII.saveFormCustom(cfg); amsAudit(staff.name, action, detail);
  };
  const go = (extra = "") => { nav(`?v=formbuilder&sec=${encodeURIComponent(sec.id)}${extra}`); };
  const hiddenSet = new Set(cfg.hidden);
  /* questions in display order: built-ins with custom questions inserted after their anchor */
  const rows = sec.fields.map(f => ({ ...f, id: `${sec.id}.${f.key}`, builtIn: true, o: cfg.overrides[`${sec.id}.${f.key}`] || null }));
  for (const c of cfg.custom.filter(c => c.section === sec.id)) {
    const r = { ...c, id: c.key, builtIn: false };
    const at = c.after ? rows.findIndex(x => x.builtIn && x.key === c.after) : -1;
    if (at < 0) { rows.push(r); continue; }
    let i = at + 1; while (rows[i] && !rows[i].builtIn) i++;
    rows.splice(i, 0, r);
  }
  const counts = { builtIn: sections.reduce((n, s) => n + s.fields.length, 0), hidden: cfg.hidden.length,
    custom: cfg.custom.length, edited: Object.keys(cfg.overrides).length };
  const editing = editKey ? rows.find(r => r.id === editKey) : null;
  const ev = editing ? (editing.builtIn ? { label: editing.o?.label || editing.label, hint: editing.o?.hint ?? editing.hint, required: editing.o?.required ?? editing.required } : editing) : {};
  const typeLabel = r => r.builtIn ? (FB_BUILTIN_TYPES[r.type] || r.type) : FB_TYPES[r.type] || r.type;
  const status = r => r.builtIn ? (deletedSet.has(r.id) ? '<span class="chip chip-rejected">Deleted</span>'
      : hiddenSet.has(r.id) ? '<span class="chip chip-inactive">Hidden</span>' : '<span class="chip chip-active">Shown</span>')
    : (r.active === false ? '<span class="chip chip-inactive">Hidden</span>' : '<span class="chip chip-active">Shown</span>');
  const isReq = r => r.builtIn ? (r.o?.required ?? r.required) : !!r.required;
  el.innerHTML = `
    <div class="crumbs"><a href="?v=dashboard">Dashboard</a><span class="sep">></span><b>Form Builder</b></div>
    <div class="page-title">Application Form Builder</div>
    <div class="page-sub">Edit, add, hide or remove the questions applicants answer. Changes apply to new and draft applications immediately; submitted applications keep the answers they were submitted with.</div>
    <div class="fb-stats">
      <div><b>${counts.builtIn}</b><span>Built-in questions</span></div>
      <div><b>${counts.custom}</b><span>Custom questions</span></div>
      <div><b>${counts.edited}</b><span>Edited questions</span></div>
      <div><b>${counts.hidden}</b><span>Hidden questions</span></div>
    </div>
    <div class="filter-chips fb-sections">${sections.map((s, i) => `<button type="button" data-sec="${escA(s.id)}" class="${s.id === sec.id ? "on" : ""}">${i + 1}. ${escA(s.title)}</button>`).join("")}
      <span class="spacer"></span>
      ${counts.custom + counts.edited + counts.hidden ? `<button type="button" class="abtn danger sm" id="fbReset">Reset all changes</button>` : ""}</div>
    <div class="grid-32 fb-grid">
      <div class="ams-card"><h3>Step ${sections.indexOf(sec) + 1} — ${escA(sec.title)} <span class="sub2">${rows.length} questions</span></h3>
        <table class="tbl fb-table"><thead><tr><th>#</th><th>Question</th><th>Answer type</th><th>Required</th><th>Status</th><th class="text-right">Actions</th></tr></thead><tbody>
        ${rows.map((r, i) => {
          const off = r.builtIn ? (hiddenSet.has(r.id) || deletedSet.has(r.id)) : r.active === false;
          const label = r.builtIn ? (r.o?.label || r.label) : r.label;
          return `<tr class="${off ? "fb-off" : ""}${editing && editing.id === r.id ? " fb-editing" : ""}">
            <td class="sub2">${i + 1}</td>
            <td><b>${escA(label)}</b>
              ${r.builtIn && r.o?.label ? `<div class="sub2">Original: ${escA(r.label)}</div>` : ""}
              ${r.conditional ? '<div class="sub2">Shown only when an earlier answer requires it</div>' : ""}
              ${!r.builtIn && (r.options || []).length ? `<div class="sub2">Options: ${escA(r.options.join(", "))}</div>` : ""}
              <div class="fb-tags">${r.builtIn ? '<span class="fb-tag">Built-in</span>' : '<span class="fb-tag fb-tag-custom">Custom</span>'}${r.builtIn && r.o ? '<span class="fb-tag fb-tag-edit">Edited</span>' : ""}${FB_LOCKED.has(r.id) ? '<span class="fb-tag fb-tag-lock">Core</span>' : ""}</div></td>
            <td class="sub2">${escA(typeLabel(r))}</td>
            <td>${isReq(r) ? '<span class="chip chip-high">Required</span>' : '<span class="chip chip-stage">Optional</span>'}</td>
            <td>${status(r)}</td>
            <td class="text-right fb-actions">
              <button type="button" class="abtn ghost sm" data-fb="edit" data-id="${escA(r.id)}">Edit</button>
              ${r.builtIn ? `${deletedSet.has(r.id)
                  ? `<button type="button" class="abtn ghost sm" data-fb="undelete" data-id="${escA(r.id)}">Restore</button>`
                  : `<button type="button" class="abtn ghost sm" data-fb="toggle" data-id="${escA(r.id)}">${off ? "Show" : "Hide"}</button>
                     <button type="button" class="abtn danger sm" data-fb="delbuilt" data-id="${escA(r.id)}">Delete</button>`}
                ${r.o ? `<button type="button" class="abtn ghost sm" data-fb="restore" data-id="${escA(r.id)}">Reset text</button>` : ""}`
                : `<button type="button" class="abtn ghost sm" data-fb="up" data-id="${escA(r.id)}" title="Move up">↑</button><button type="button" class="abtn ghost sm" data-fb="down" data-id="${escA(r.id)}" title="Move down">↓</button>
                   <button type="button" class="abtn danger sm" data-fb="delete" data-id="${escA(r.id)}">Delete</button>`}
            </td></tr>`; }).join("")}
        </tbody></table>
      </div>
      <div class="ams-card fb-editor"><h3>${editing ? (editing.builtIn ? "Edit built-in question" : "Edit custom question") : "Add a new question"}</h3>
        <form id="fbForm" class="inline-form" style="margin:0">
          <label>Question text *</label>
          <textarea name="label" rows="2" maxlength="300" required>${escA(ev.label || "")}</textarea>
          ${editing?.builtIn ? `<label>Answer type</label><input value="${escA(typeLabel(editing))}" disabled>
            <div class="sub2" style="margin-top:3px">The answer type of built-in questions is fixed because reports, scoring and AMS records depend on it.</div>`
            : `<label>Answer type *</label><select name="type">${Object.entries(FB_TYPES).map(([k, v]) => `<option value="${k}" ${ev.type === k ? "selected" : ""}>${v}</option>`).join("")}</select>
          <div class="fb-opt" data-for="select checks"><label>Choices * <span class="sub2">(one per line)</span></label>
            <textarea name="options" rows="4" placeholder="Option 1&#10;Option 2&#10;Option 3">${escA((ev.options || []).join("\n"))}</textarea></div>
          <div class="fb-opt" data-for="file"><label>Accepted file types</label>
            <input name="extensions" value="${escA((ev.extensions || ["pdf", "jpg", "png"]).join(", "))}" placeholder="pdf, jpg, png">
            <label>Maximum number of files</label><input type="number" name="maxCount" min="1" max="10" value="${ev.maxCount || 3}"></div>
          <div class="fb-opt" data-for="text textarea"><label>Maximum characters</label>
            <input type="number" name="max" min="10" max="5000" value="${ev.max || ""}" placeholder="Default: 300 short / 2000 paragraph"></div>
          <label>Position in "${escA(sec.title)}"</label>
          <select name="after"><option value="">At the end of this step</option>${sec.fields.map(f => `<option value="${escA(f.key)}" ${ev.after === f.key ? "selected" : ""}>After: ${escA((cfg.overrides[`${sec.id}.${f.key}`]?.label || f.label).slice(0, 70))}</option>`).join("")}</select>`}
          <label>Help text for applicants</label>
          <textarea name="hint" rows="2" maxlength="400" placeholder="Optional guidance shown under the question">${escA(ev.hint || "")}</textarea>
          ${editing?.builtIn && editing.conditional ? "" : `<label class="fb-check"><input type="checkbox" name="required" ${ev.required ? "checked" : ""}> Applicants must answer this question</label>`}
          <div class="qa-row" style="margin-top:12px">
            <button class="abtn sm">${editing ? "Save changes" : `${IC.plus} Add question`}</button>
            ${editing ? `<button type="button" class="abtn ghost sm" id="fbCancel">Cancel</button>` : ""}
          </div>
        </form>
        ${cfg.updatedAt ? `<div class="sub2" style="margin-top:10px">Last change: ${amsFmtDateTime(cfg.updatedAt)} by ${escA(cfg.updatedBy || "—")}</div>` : ""}
      </div>
    </div>`;

  $$ams(".fb-sections [data-sec]", el).forEach(b => b.addEventListener("click", () => { nav(`?v=formbuilder&sec=${encodeURIComponent(b.dataset.sec)}`); }));
  const form = $ams("#fbForm", el), typeSel = form.type;
  const syncOpts = () => $$ams(".fb-opt", form).forEach(d => d.classList.toggle("hidden", !typeSel || !d.dataset.for.split(" ").includes(typeSel.value)));
  if (typeSel) { typeSel.addEventListener("change", syncOpts); syncOpts(); }
  $ams("#fbCancel", el)?.addEventListener("click", () => go());
  $ams("#fbReset", el)?.addEventListener("click", () => {
    if (!sure("remove ALL custom questions, edits and hidden/deleted settings and restore the original form? Answers already entered by applicants are kept")) return;
    const n = cfg.custom.length; cfg.custom = []; cfg.hidden = []; cfg.overrides = {}; cfg.deleted = [];
    save("Form reset to original", `${n} custom question(s) removed`); go();
  });
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const label = form.label.value.trim(), hint = form.hint.value.trim(), req = form.required ? form.required.checked : undefined;
    if (!label) { alert("Please enter the question text."); return; }
    if (!sure(editing ? `save the changes to "${label}"?` : `add the new question "${label}" to "${sec.title}"?`)) return;
    if (editing?.builtIn) {
      const o = {};
      if (label !== editing.label) o.label = label;
      if (hint !== (editing.hint || "")) o.hint = hint;
      if (req !== undefined && req !== editing.required) o.required = req;
      if (Object.keys(o).length) cfg.overrides[editing.id] = o; else delete cfg.overrides[editing.id];
      save("Form question edited", `${sec.title}: ${label}`); go();
      return;
    }
    const type = typeSel.value;
    const options = [...new Set(form.options.value.split("\n").map(x => x.trim()).filter(Boolean))];
    if (["select", "checks"].includes(type) && options.length < 2) { alert("Please enter at least two choices (one per line)."); return; }
    const q = { section: sec.id, label, type, hint, required: !!req, after: form.after.value,
      options: ["select", "checks"].includes(type) ? options : [] };
    if (type === "file") {
      q.extensions = [...new Set(form.extensions.value.split(/[,\s]+/).map(x => x.replace(/^\./, "").toLowerCase()).filter(x => /^[a-z0-9]{1,5}$/.test(x)))];
      if (!q.extensions.length) q.extensions = ["pdf"];
      q.maxCount = Math.min(10, Math.max(1, +form.maxCount.value || 1));
    }
    if (["text", "textarea"].includes(type) && +form.max.value) q.max = Math.min(5000, Math.max(10, +form.max.value));
    if (editing) {
      Object.assign(cfg.custom.find(c => c.key === editing.key), q);
      save("Form question edited", `${sec.title}: ${label}`);
    } else {
      cfg.custom.push({ ...q, key: "cq_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6), active: true, createdAt: new Date().toISOString(), createdBy: staff.name });
      save("Form question added", `${sec.title}: ${label}`);
    }
    go();
  });
  $$ams("[data-fb]", el).forEach(b => b.addEventListener("click", () => {
    const r = rows.find(x => x.id === b.dataset.id); if (!r) return;
    const act = b.dataset.fb, label = r.builtIn ? (r.o?.label || r.label) : r.label;
    if (act === "edit") return go(`&edit=${encodeURIComponent(r.id)}`);
    if (act === "toggle") {
      if (r.builtIn) {
        const on = hiddenSet.has(r.id);
        if (!sure(`${on ? "show" : "hide"} "${label}" ${on ? "in" : "from"} the application form${on ? "" : "? Follow-up questions that depend on it will also stay hidden."}`)) return;
        cfg.hidden = on ? cfg.hidden.filter(x => x !== r.id) : [...cfg.hidden, r.id];
        save(on ? "Form question shown" : "Form question hidden", `${sec.title}: ${label}`);
      } else {
        const c = cfg.custom.find(c => c.key === r.key);
        if (!sure(`${c.active === false ? "show" : "hide"} "${label}"?`)) return;
        c.active = c.active === false;
        save(c.active ? "Form question shown" : "Form question hidden", `${sec.title}: ${label}`);
      }
      return go();
    }
    if (act === "delbuilt") {
      if (!sure(`permanently delete the built-in question "${label}"? Applicants will no longer see it; answers already entered stay in their records`)) return;
      cfg.deleted = [...deletedSet, r.id];
      cfg.hidden = cfg.hidden.filter(x => x !== r.id);
      save("Built-in question deleted", `${sec.title}: ${label}`); return go();
    }
    if (act === "undelete") {
      if (!sure(`restore the built-in question "${label}" to the application form?`)) return;
      cfg.deleted = cfg.deleted.filter(x => x !== r.id);
      save("Built-in question restored", `${sec.title}: ${label}`); return go();
    }
    if (act === "restore") {
      if (!sure(`restore the original wording and settings of "${r.label}"?`)) return;
      delete cfg.overrides[r.id]; save("Form question restored", `${sec.title}: ${r.label}`); return go();
    }
    if (act === "delete") {
      if (!sure(`delete the question "${label}"? Applicants will no longer see it; answers already entered stay in their records`)) return;
      cfg.custom = cfg.custom.filter(c => c.key !== r.key); save("Form question deleted", `${sec.title}: ${label}`); return go();
    }
    if (act === "up" || act === "down") {
      const mine = cfg.custom.filter(c => c.section === sec.id && (c.after || "") === (r.after || ""));
      const i = mine.findIndex(c => c.key === r.key), j = act === "up" ? i - 1 : i + 1;
      if (j < 0 || j >= mine.length) {
        /* step past the neighbouring built-in question */
        const keys = sec.fields.map(f => f.key), pos = r.after ? keys.indexOf(r.after) : keys.length - 1;
        const c = cfg.custom.find(c => c.key === r.key), rest = cfg.custom.filter(x => x !== c);
        if (act === "up") {
          if (pos <= 0) { alert("A question cannot be placed before the first question of a step."); return; }
          c.after = keys[pos - 1]; cfg.custom = [...rest, c];
        } else {
          if (pos >= keys.length - 1) { alert("This question is already at the end of the step."); return; }
          c.after = keys[pos + 1]; cfg.custom = [c, ...rest];
        }
      } else {
        const a = cfg.custom.indexOf(mine[i]), z = cfg.custom.indexOf(mine[j]);
        [cfg.custom[a], cfg.custom[z]] = [cfg.custom[z], cfg.custom[a]];
      }
      save("Form question moved", `${sec.title}: ${label}`); return go();
    }
  }));
}

/* ---------- router ---------- */
const content = $ams("#amsContent");
const ROUTES = {
  dashboard: viewDashboard, applicants: viewApplicants, applicant: viewApplicant,
  meetings: viewMeetings, tasks: viewTasks, chat: viewChat, evaluations: viewEvaluations,
  procurement: viewProcurement, reports: viewReports, documents: viewDocuments,
  team: viewTeam, settings: viewSettings, formbuilder: viewFormBuilder,
  reportdoc: viewReportDoc,
};
const VIEW_PERM = {
  applicants: "view_applicants", applicant: "view_applicants", meetings: "manage_meetings",
  tasks: "manage_tasks", evaluations: "evaluate", procurement: "manage_procurement",
  reports: "view_reports", documents: "view_applicants", team: "manage_staff", formbuilder: "manage_form", reportdoc: "view_reports",
};

/* safe row/button navigation (no inline JS with user-derived ids) */
document.addEventListener("click", (e) => {
  const t = e.target.closest("[data-go]");
  if (t && !e.target.closest("a,button:not([data-go]),input,select,textarea")) nav(t.dataset.go);
});
/* "Filter" buttons: quick text filter over the table in the same card */
document.addEventListener("click", (e) => {
  const b = e.target.closest(".btn-filter");
  if (!b) return;
  const card = b.closest(".ams-card");
  let inp = card.querySelector(".tbl-search");
  if (!inp) {
    inp = document.createElement("input");
    inp.className = "tbl-search"; inp.placeholder = "Type to filter rows…";
    b.closest(".filter-chips").after(inp);
    inp.addEventListener("input", () => {
      const q = inp.value.toLowerCase();
      card.querySelectorAll(".tbl tbody tr").forEach(r => r.style.display = fuzzyMatch(inp.value, r.textContent) ? "" : "none");
    });
  }
  inp.focus();
});

/* ---------- single-page navigation ----------
   Same-page moves only re-render the content area and update the address bar,
   so the sidebar and top bar never reload or flash. */
function nav(url) { history.pushState(null, "", url); route(); }
function route() {
  readRoute();
  $$ams("#amsNav a").forEach(a => a.classList.toggle("active",
    a.dataset.v === view || (view === "applicant" && a.dataset.v === "applicants")));
  content.style.opacity = "0";
  const needed = VIEW_PERM[view];
  if (staff.mustChangePassword && view !== "settings") {
    history.replaceState(null, "", "?v=settings&pw=1");
    readRoute();
  }
  const perm = VIEW_PERM[view];
  if (perm && !can(perm)) {
    content.innerHTML = `<div class="ams-card"><h3>Access restricted</h3>
      <div class="empty-state">Your role does not have permission to access this section.
      Contact the Application &amp; Administration Manager to request access.</div></div>`;
  } else {
    (ROUTES[view] || viewDashboard)(content);
  }
  (typeof requestAnimationFrame === "function" ? requestAnimationFrame : f => setTimeout(f, 0))(() => { content.style.opacity = "1"; });
  if (typeof window.scrollTo === "function") window.scrollTo(0, 0);
}
/* intercept links that stay inside the staff portal */
document.addEventListener("click", (e) => {
  const a = e.target.closest("a[href]");
  if (!a || e.defaultPrevented || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
  const href = (a.getAttribute("href") || "").trim();
  if (!href || href.startsWith("#") || a.target === "_blank" || a.hasAttribute("download") ||
      /^(javascript|mailto|tel):/i.test(href)) return;
  const u = new URL(href, location.href);
  if (u.origin !== location.origin || u.pathname !== location.pathname) return;
  e.preventDefault();
  nav(href);
});
window.addEventListener("popstate", route);

try { amsSyncPortal(); } catch (e) { console.error("Portal sync failed:", e); }
route();
